// Content structures. The tables themselves (kBlocks, kItems, kUnits, kSectors)
// are generated by tools/build_assets.py from upstream/Mindustry Java sources.
#pragma once
#include <cstdint>

namespace mdt {

constexpr float tilesize = 8.f;  // Vars.tilesize

enum class BType : uint8_t {
    Air, Floor, Ore, Overlay, StaticWall, Prop,
    Conveyor, Junction, Router, Sorter, OverflowGate, Bridge,
    Drill, Crafter, ConsumeGen, PowerNode, Battery,
    ItemTurret, Wall, Core, Storage,
    Solar  // SolarGenerator
};

// mindustry.type.Category order
enum Category : int8_t {
    CatNone = -1, CatTurret, CatProduction, CatDistribution, CatLiquid, CatPower,
    CatDefense, CatCrafting, CatUnits, CatEffect, CatLogic, CAT_COUNT
};

struct Stack { int16_t item; int16_t amount; };

struct BulletDef {
    float speed, damage, lifetime, ammoMultiplier, reloadMultiplier;
    float splashDamage, splashRadius, buildingDamageMultiplier, homingPower;
    bool collidesAir, collidesGround;
    uint8_t kind;  // 0 basic, 1 flak, 2 artillery
};

struct AmmoDef { int16_t item; BulletDef bullet; };

struct BlockDef {
    const char* name;
    BType type;
    int8_t category;
    uint8_t size;
    bool solid, rotate, buildable;
    float health, buildCost;
    int itemCapacity;
    Stack req[4]; int nreq;
    Stack consumes[3]; int nconsumes;
    Stack output;
    float craftTime, powerUse, powerBuffer;
    int16_t spr, sprTop, sprRot, sprTeam, sprVar, sprExtra;
    int variants;
    int16_t itemDrop;
    bool isLiquid, isDeep;
    float speedMultiplier;
    float speed, displayedSpeed;
    int capacity;
    float range;
    float drillTime, hardnessMul, warmupSpeed;
    float powerProduction, itemDuration;
    int maxNodes;
    float laserRange, reload, rotateSpeed, inaccuracy, shootCone;
    int maxAmmo, shots;
    bool targetAir, targetGround;
    AmmoDef ammo[3]; int nammo;
    int16_t sprIcon;  // composite of Block.icons(), 32x32 UI size; sprIcon + 1 = 16x16
    bool squareSprite;  // Block.squareSprite (Generators: no pixel below 90% alpha)
};

struct ItemDef {
    const char* name;
    uint32_t color;
    float cost;
    int hardness;
    float flammability, explosiveness, healthScaling;
    bool buildable;
    int16_t spr;
};

struct WeaponDef {
    float reload, x, y;
    bool mirror;
    BulletDef bullet;
};

struct UnitDef {
    const char* name;
    float speed, health, hitSize, rotateSpeed, drag, accel;
    bool flying;
    float mineSpeed; int mineTier;
    float buildSpeed; int itemCapacity;
    float range;
    WeaponDef weapon;
    int16_t spr, sprCell, sprBase, sprLeg, sprWeapon;
    float engineOffset;
};

struct SectorDef {
    const char* name;
    int captureWave, difficulty;
    float startWaveTimeMultiplier;
};

extern const ItemDef kItems[];
extern const BlockDef kBlocks[];
extern const unsigned char kBlockTier[];
extern const UnitDef kUnits[];
extern const SectorDef kSectors[];

}  // namespace mdt
